const M = require('lv-automation').metaAds;
const out = [];
const client = M.createClient({ token: $env.META_SYSTEM_USER_TOKEN, apiVersion: $env.META_API_VERSION || 'v23.0', maxInlineWaitMs: 20000 });
for (const it of $input.all()) {
  const b = it.json;
  try {
    // last_3d re-reads yesterday/day-before so late attribution revisions overwrite (upsert by ad/day).
    const r = await client.getInsights({ adAccountId: b.ad_account_id, level: 'ad', datePreset: 'last_3d', lastFetchedAt: b.insights_last_fetched_at });
    // Ad status / budget cache (ad_objects). Non-fatal: a failure here never blocks the metrics upsert.
    let objects = [];
    try { objects = (await client.getAdObjects({ adAccountId: b.ad_account_id, brandId: b.brand_id, lastFetchedAt: b.insights_last_fetched_at })).rows; } catch (e2) { objects = []; }
    out.push({ json: { status: 'ok', brand_id: b.brand_id, fetched_at: r.fetched_at, usage_pct: r.usage && r.usage.pct, truncated: r.truncated, rows: M.insightsToAdMetrics(r.rows, { brandId: b.brand_id }), objects } });
  } catch (e) {
    const status = e.code === 'RATE_LIMIT_BACKOFF' || e.code === 'RATE_LIMIT' ? 'backoff' : e.code === 'TOO_SOON' ? 'too_soon' : 'error';
    out.push({ json: { status, brand_id: b.brand_id, code: e.code || 'ERR', message: String(e.message).slice(0, 300), retry_after_ms: e.retryAfterMs || null } });
  }
}
return out;
